/// For example: `?l?d` expands to lowercase letters + digits,
/// `aeiou` is just those 5 vowels, `?l@#$` is lowercase + @, #, $.
pub fn parse_custom_charset(definition: &str) -> Result<Vec<char>, FinderError> {
